import { createDataRouter } from "@kasperrt/smolter/preact";
import { withRouteDiscovery } from "@kasperrt/smolter/preact/discovery";

const router = createDataRouter(routes, {
  discover: withRouteDiscovery(async (url, { signal }) => {
    const response = await fetch(`/routes?path=${url.pathname}`, { signal });
    return response.ok ? toRoutes(await response.json()) : [];
  }),
});
